import React, { useState, useEffect } from "react";
import logo from '../../assets/images/logogete.png';
import "./Navbar.css";
import { useNavigate, useLocation } from "react-router-dom";
import { FaBars, FaTimes } from "react-icons/fa";

function Navbar() {
  const [isMobile, setIsMobile] = useState(false);
  const [isScrolled, setIsScrolled] = useState(false);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const [currentPage, setCurrentPage] = useState("/");

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  };

  // Gestion du scroll pour l'effet de background
  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 10) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Mise à jour de la page actuelle
  useEffect(() => {
    localStorage.setItem("current", currentPage);
  }, [currentPage]);

  useEffect(() => {
    const currentPath = location.pathname;
    setCurrentPage(getPageNameFromPath(currentPath));
  }, [location]);

  // Gestion du resize pour mobile
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth >= 780) {
        setIsMobile(false);
      }
    };

    window.addEventListener("resize", handleResize);
    return () => {
      window.removeEventListener("resize", handleResize);
    };
  }, []);

  const getPageNameFromPath = (path) => {
    const pageName = path.substring(1);
    return pageName || "/";
  };

  return (
    <header className={`navbar-container ${isScrolled ? 'scrolled' : ''}`}>
      <nav className="navbar">
        {/* Logo */}
        <div className="navbar-logo">
          <img
            src={logo}
            alt="BIG DAY Logo"
            onClick={() => {
              navigate("/");
              setCurrentPage("/");
              scrollToTop();
            }}
          />
        </div>

        {/* Navigation Links */}
        <ul className={isMobile ? "navbar-links-mobile" : "navbar-links"}>
          <li>
            <a
              href="#"
              className={currentPage === "/" ? "active" : ""}
              onClick={(e) => {
                e.preventDefault();
                navigate("/");
                setCurrentPage("/");
                scrollToTop();
                setIsMobile(false);
              }}
            >
              Accueil
            </a>
          </li>

          {/* Dropdown À Propos */}
          <li 
            className="dropdown"
            onMouseEnter={() => setIsDropdownOpen(true)}
            onMouseLeave={() => setIsDropdownOpen(false)}
          >
            <a
              href="#"
              className={currentPage === "program" ? "active" : ""}
              onClick={(e) => {
                e.preventDefault();
                navigate("/program");
                setCurrentPage("program");
                scrollToTop();
                setIsMobile(false);
              }}
            >
              À propos
            </a>
            {isDropdownOpen && !isMobile && (
              <ul className="dropdown-menu">
                <li>
                  <a
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      navigate("/program?section=Theme");
                      setCurrentPage("program");
                      scrollToTop();
                    }}
                  >
                    Thème
                  </a>
                </li>
                <li>
                  <a
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      navigate("/program?section=Panels");
                      setCurrentPage("program");
                      scrollToTop();
                    }}
                  >
                    Panels
                  </a>
                </li>
                <li>
                  <a
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      navigate("/program?section=Workshops");
                      setCurrentPage("program");
                      scrollToTop();
                    }}
                  >
                    Workshops
                  </a>
                </li>
              </ul>
            )}
          </li>

          <li>
            <a
              href="#"
              className={currentPage === "collaboration" ? "active" : ""}
              onClick={(e) => {
                e.preventDefault();
                navigate("/collaboration");
                setCurrentPage("collaboration");
                scrollToTop();
                setIsMobile(false);
              }}
            >
              Collaboration
            </a>
          </li>

          <li>
            <a
              href="#"
              className={currentPage === "programme" ? "active" : ""}
              onClick={(e) => {
                e.preventDefault();
                navigate("/programme");
                setCurrentPage("programme");
                scrollToTop();
                setIsMobile(false);
              }}
            >
              Programme
            </a>
          </li>

          {/* Legacy */}
          <li>
            <a
              href="#"
              className={currentPage === "glance" ? "active" : ""}
              onClick={(e) => {
                e.preventDefault();
                navigate("/glance");
                setCurrentPage("glance");
                scrollToTop();
                setIsMobile(false);
              }}
            >
              Legacy
            </a>
          </li>

          <li>
            <a
              href="#"
              className={currentPage === "contact" ? "active" : ""}
              onClick={(e) => {
                e.preventDefault();
                navigate("/contact");
                setCurrentPage("contact");
                scrollToTop();
                setIsMobile(false);
              }}
            >
              Contact
            </a>
          </li>

          {/* Inscription en mobile */}
          <li className="mobile-inscription">
            <a
              href="#"
              className="inscription-button"
              onClick={(e) => {
                e.preventDefault();
                navigate("/Register");
                setCurrentPage("Register");
                scrollToTop();
                setIsMobile(false);
              }}
            >
              Inscription
            </a>
          </li>
        </ul>

        {/* Bouton Inscription Desktop */}
        <div className="navbar-action">
          <a
            href="#"
            className="inscription-button"
            onClick={(e) => {
              e.preventDefault();
              navigate("/Register");
              setCurrentPage("Register");
              scrollToTop();
            }}
          >
            Inscription
          </a>
        </div>

        {/* Bouton Hamburger */}
        <button className="mobile-toggle" onClick={() => setIsMobile(!isMobile)}>
          <FaBars />
        </button>
      </nav>
    </header>
  );
}
